-- =============================================================================
-- V13: REFACTOR MASTER DATA HIERARCHY TREE (191 NODES)
-- =============================================================================

-- Bootstrapping Base Active Status 'ACT'
VALUES ('ACTIVO', 'ACT', NULL, NULL) 
ON CONFLICT (short_name) DO UPDATE SET full_name = EXCLUDED.full_name;

UPDATE master_data 
SET status_id = (SELECT id FROM master_data WHERE short_name = 'ACT') 
WHERE short_name = 'ACT' AND status_id IS NULL;


-- Connect ACT to STSGEN parent
UPDATE master_data 
SET parent_id = (SELECT id FROM master_data WHERE short_name = 'STSGEN') 
WHERE short_name = 'ACT';
